import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, invoiceTotals } from '../src/totals.js';
import { createInvoice, issueInvoice, addLine, removeLine, applyVoucher } from '../src/invoices.js';

test('lineTotal calculates qty × unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 8500 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 42500);
});

test('lineTotal handles various quantities and prices', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 100 }).value, 100);
  assert.equal(lineTotal({ qty: 10, unitPrice: 1000 }).value, 10000);
  assert.equal(lineTotal({ qty: 3, unitPrice: 120000 }).value, 360000);
});

test('lineTotal validates qty is a positive integer', () => {
  const cases = [
    { qty: 0, error: 'QTY_INVALID' },
    { qty: -5, error: 'QTY_INVALID' },
    { qty: 1.5, error: 'QTY_INVALID' },
    { qty: '5', error: 'QTY_INVALID' },
    { qty: null, error: 'QTY_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: c.qty, unitPrice: 100 });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject qty=${c.qty}`);
  }
});

test('lineTotal validates unitPrice is a non-negative integer', () => {
  const cases = [
    { unitPrice: -100, error: 'AMOUNT_INVALID' },
    { unitPrice: 1.5, error: 'AMOUNT_INVALID' },
    { unitPrice: '100', error: 'AMOUNT_INVALID' },
    { unitPrice: null, error: 'AMOUNT_INVALID' },
  ];
  for (const c of cases) {
    const r = lineTotal({ qty: 1, unitPrice: c.unitPrice });
    assert.deepEqual(r, { ok: false, error: c.error }, `should reject unitPrice=${c.unitPrice}`);
  }
});

test('lineTotal accepts zero unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 0 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('invoiceTotals calculates subtotal, discount, vat and total', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 21 },
      { qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 162500);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 34125);
  assert.equal(r.value.total, 196625);
});

test('invoiceTotals sums multiple line totals', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, vatRate: 21 },
      { qty: 2, unitPrice: 200, vatRate: 21 },
      { qty: 1, unitPrice: 500, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 1200);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 252);
  assert.equal(r.value.total, 1452);
});

test('invoiceTotals returns an object with subtotal, discount, vat and total', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 100, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.ok('subtotal' in r.value);
  assert.ok('discount' in r.value);
  assert.ok('vat' in r.value);
  assert.ok('total' in r.value);
});

test('invoiceTotals validates invoice has lines', () => {
  const cases = [null, {}, { lines: null }, { lines: [] }];
  for (const invoice of cases) {
    const r = invoiceTotals(invoice);
    assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
  }
});

test('invoiceTotals propagates line validation errors', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100 },
      { qty: 0, unitPrice: 100 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('invoiceTotals works with real invoices from createInvoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5 * 8500 + 1 * 120000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 34125);
  assert.equal(r.value.total, 196625);
});

test('invoiceTotals calculates discount on a single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 10 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5000);
  assert.equal(r.value.discount, 500);
  assert.equal(r.value.total, 4500);
});

test('invoiceTotals calculates discount with decimal percentages', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 12.5 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5000);
  assert.equal(r.value.discount, 625);
  assert.equal(r.value.total, 4375);
});

test('invoiceTotals handles multiple lines with different discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 10 },
      { qty: 2, unitPrice: 2000, discountPercent: 20 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 9000);
  assert.equal(r.value.discount, 500 + 800);
  assert.equal(r.value.total, 9000 - 1300);
});

test('invoiceTotals handles mix of lines with and without discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 10 },
      { qty: 2, unitPrice: 1000 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 7000);
  assert.equal(r.value.discount, 500);
  assert.equal(r.value.total, 6500);
});

test('invoiceTotals with 0% discount', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.total, 5000);
});

test('invoiceTotals with 100% discount', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 1000, discountPercent: 100 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5000);
  assert.equal(r.value.discount, 5000);
  assert.equal(r.value.total, 0);
});

test('invoiceTotals with real invoices from createInvoice and discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  const expectedSubtotal = 5 * 8500 + 1 * 120000;
  const line1Discount = (5 * 8500) * 0.2;
  const line2Discount = 120000 * 0.05;
  const expectedDiscount = line1Discount + line2Discount;
  const line1DiscountedAmount = (5 * 8500) - line1Discount;
  const line2DiscountedAmount = 120000 - line2Discount;
  const expectedVat = Math.round(line1DiscountedAmount * 0.21) + Math.round(line2DiscountedAmount * 0.21);
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat;
  assert.equal(r.value.subtotal, expectedSubtotal);
  assert.equal(r.value.discount, expectedDiscount);
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals calculates gold tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 85000);
  assert.equal(r.value.discount, 4250);
  const discountedAmount = 85000 - 4250;
  const expectedVat = Math.round(discountedAmount * 0.21);
  const expectedTotal = 85000 - 4250 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals calculates silver tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 85000);
  assert.equal(r.value.discount, 2125);
  const discountedAmount = 85000 - 2125;
  const expectedVat = Math.round(discountedAmount * 0.21);
  const expectedTotal = 85000 - 2125 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals standard tier has no discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 85000);
  assert.equal(r.value.discount, 0);
  const expectedVat = Math.round(85000 * 0.21);
  const expectedTotal = 85000 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals calculates VAT on single line', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 2100);
  assert.equal(r.value.total, 12100);
});

test('invoiceTotals calculates VAT after discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  assert.equal(r.value.discount, 1000);
  const discountedAmount = 9000;
  const expectedVat = Math.round(discountedAmount * 0.21);
  const expectedTotal = 10000 - 1000 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals handles multiple VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, vatRate: 21 },
      { qty: 2, unitPrice: 1000, vatRate: 9 },
      { qty: 1, unitPrice: 1000, vatRate: 0 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 8000);
  assert.equal(r.value.discount, 0);
  const vat21 = Math.round(5000 * 0.21);
  const vat9 = Math.round(2000 * 0.09);
  const vat0 = Math.round(1000 * 0.00);
  const expectedVat = vat21 + vat9 + vat0;
  const expectedTotal = 8000 + expectedVat;
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

test('invoiceTotals VAT is rounded per line', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 100, vatRate: 21 },
      { qty: 3, unitPrice: 100, vatRate: 21 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 600);
  const vat1 = Math.round(300 * 0.21);
  const vat2 = Math.round(300 * 0.21);
  const expectedVat = vat1 + vat2;
  assert.equal(r.value.vat, expectedVat);
});

test('invoiceTotals zero VAT rate results in no VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 0 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 10000);
  assert.equal(r.value.discount, 0);
  assert.equal(r.value.vat, 0);
  assert.equal(r.value.total, 10000);
});

test('invoiceTotals includes voucher in calculation', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const totals1 = invoiceTotals(invoice.value);
  assert.equal(totals1.ok, true);
  const vouchered = applyVoucher(invoice.value, { code: 'SAVE10', amount: 50 });
  assert.equal(vouchered.ok, true);
  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.ok, true);
  assert.equal(totals2.value.voucher, 50);
  assert.equal(totals2.value.total, totals1.value.total - 50);
});

test('invoiceTotals returns 0 voucher when none applied', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const totals = invoiceTotals(invoice.value);
  assert.equal(totals.ok, true);
  assert.equal(totals.value.voucher, 0);
});

test('invoiceTotals voucher comes after VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoice.ok, true);
  const totals1 = invoiceTotals(invoice.value);
  const vouchered = applyVoucher(invoice.value, { code: 'SAVE100', amount: 10000 });
  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.ok, true);
  const expectedTotal = totals1.value.subtotal - totals1.value.discount + totals1.value.vat - 10000;
  assert.equal(totals2.value.total, expectedTotal);
});

test('invoiceTotals with large voucher amount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const totals1 = invoiceTotals(invoice.value);
  const vouchered = applyVoucher(invoice.value, { code: 'SAVE_ALL', amount: totals1.value.total });
  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.value.total, 0);
});

test('invoiceTotals with voucher exceeding total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const totals1 = invoiceTotals(invoice.value);
  const vouchered = applyVoucher(invoice.value, { code: 'SAVE_EXCESS', amount: totals1.value.total + 1000 });
  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.value.total, 0);
});

