test('invoiceTotals voucher comes after VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  assert.equal(invoice.ok, true);
  const totals1 = invoiceTotals(invoice.value);
  const vouchered = applyVoucher(invoice.value, { code: 'SAVE100', amount: 10000 });
  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.ok, true);
  // Voucher is subtracted after VAT: subtotal - discount + vat - voucher
  const expectedTotal = totals1.value.subtotal - totals1.value.discount + totals1.value.vat - 10000;
  assert.equal(totals2.value.total, expectedTotal);
});

