  const vouchered = applyVoucher(invoice.value, { code: 'SAVE_ALL', amount: totals1.value.total });
  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.value.total, 0);
});

test('invoiceTotals with voucher exceeding total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 2 }],
  });
  assert.equal(invoice.ok, true);
  const totals1 = invoiceTotals(invoice.value);
  const vouchered = applyVoucher(invoice.value, { code: 'SAVE_EXCESS', amount: totals1.value.total + 1000 });
  const totals2 = invoiceTotals(vouchered.value);
  assert.equal(totals2.value.total, 0);
});

