      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoice.ok, true);
  const r = invoiceTotals(invoice.value);
  assert.equal(r.ok, true);
  const expectedSubtotal = 5 * 8500 + 1 * 120000;
  const line1Discount = (5 * 8500) * 0.2;
  const line2Discount = 120000 * 0.05;
  const expectedDiscount = line1Discount + line2Discount;
  const line1DiscountedAmount = (5 * 8500) - line1Discount;
  const line2DiscountedAmount = 120000 - line2Discount;
  const expectedVat = Math.round(line1DiscountedAmount * 0.21) + Math.round(line2DiscountedAmount * 0.21);
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat;
  assert.equal(r.value.subtotal, expectedSubtotal);
  assert.equal(r.value.discount, expectedDiscount);
  assert.equal(r.value.vat, expectedVat);
  assert.equal(r.value.total, expectedTotal);
});

